// Generated by scaffold-email
// MailService — the injectable any module (auth, otp, notification) uses to send
// transactional email. Thin convenience wrappers over MailClient.send(); add more
// as needed. Best-effort: returns false rather than throwing.
import { Injectable } from '@nestjs/common';
import { MailClient } from './mail.client';

@Injectable()
export class MailService {
  constructor(private readonly mail: MailClient) {}

  send(to: string, subject: string, html: string, text?: string): Promise<boolean> {
    return this.mail.send(to, subject, html, text);
  }

  sendVerificationEmail(to: string, codeOrLink: string): Promise<boolean> {
    return this.mail.send(to, 'Verify your email',
      '<p>Your verification code/link: <b>' + codeOrLink + '</b></p>');
  }

  sendPasswordResetEmail(to: string, link: string): Promise<boolean> {
    return this.mail.send(to, 'Reset your password',
      '<p>Reset your password: <a href="' + link + '">' + link + '</a></p>');
  }
}
